/** Accepted character identity metadata copied from DataDump's provenance-preserving
 * identities dataset. Original text and community metadata remain separate claims.
 * No owned instances, final-version base stats, skill magnitudes, or cut-in bindings.
 * Generated from datasets/hunters/identities.json; DataDump is a read-only source.
 */
export interface CharacterClaim { value: string | null; provenance: { source_id: string; path: string; sha256: string; locator: string; label: string; [key: string]: unknown } }
export interface CharacterIdentity { id: string; claims: Partial<Record<"name" | "title" | "summary" | "role" | "element" | "rarity" | "weapon" | "armor" | "accessory" | "victory", CharacterClaim>> }
/** Native enum vocabulary is recovered; assigning a hunter's element/role uses
 * its COMMUNITY-SOURCED catalogue claim, never the Episode actor sharing its art. */
const roleEnums: Record<string, number> = { Offense: 1, Defense: 2, Bomber: 3, Support: 4 };
const elementEnums: Record<string, number> = { Fire: 1, Ice: 2, Lightning: 3 };

export function characterMaterialCoverage(packageNames: readonly string[], publishedIds: readonly string[]) {
  const selected = new Set(packageNames);
  const published = new Set(publishedIds);
  return characterIdentities.map((identity) => {
    // Only base art is bound here. Awakened/costume identities are preserved in
    // the catalogue, but their resource convention and ordinary selection are
    // not sufficiently established for automatic publication.
    const baseIdentity = /^\d{3}$/.test(identity.id);
    const required = [`C${identity.id}.jet`, `C${identity.id}_Q.jet`, `C${identity.id}_EFT.jet`, `C${identity.id}_SND.jet`];
    const missingPackages = required.filter((name) => !selected.has(name));
    const role = roleEnums[identity.claims.role?.value ?? ""];
    const attr = elementEnums[identity.claims.element?.value ?? ""];
    const name = identity.claims.name?.value;
    const metadataComplete = !!name && !!role && !!attr;
    return {
      id: identity.id, name: name ?? null, role: role ?? null, attr: attr ?? null,
      published: published.has(identity.id), baseIdentity, required, missingPackages,
      materialComplete: baseIdentity && missingPackages.length === 0,
      referenceCandidate: baseIdentity && metadataComplete && missingPackages.length === 0 && !published.has(identity.id),
      finalVersionBaseStats: "UNKNOWN", skillMagnitudes: "UNKNOWN", nativeOrdinaryValidation: "PENDING",
    };
  });
}

/** Constructs additional ordinary reference rows only from metadata with all
 * four explicitly selected original material packages. The caller must supply
 * separately documented local stats and neutral skill slots: a material match
 * never promotes archive observations or artwork into original balance.
 * Existing references and ownership are outside this function's scope. */
export function additionalMaterialReferences<Stat extends Record<string, unknown>, Skill>(options: {
  packageNames: readonly string[]; publishedIds: readonly string[];
  fixtureStats: readonly Stat[];
  neutralSkillSlots: (refId: string) => Skill[];
  projectStats?: (refId: string, stat: Stat) => Stat;
}) {
  if (!options.fixtureStats.length || options.fixtureStats.some((row) => !Number.isInteger(row.rank)))
    throw new Error("Explicit local fixture stat rank rows required");
  return characterMaterialCoverage(options.packageNames, options.publishedIds)
    .filter((row) => row.referenceCandidate).map((row) => ({
      is_main: 0, id: row.id, ref_id: row.id, thumb: `C${row.id}`,
      base: { id: row.id, char_id: row.id, name: row.name!, is_main: 0,
        attr: row.attr!, role: row.role!, res_prefix: `C${row.id}`,
        is_source: 0, source_field: 0, cool_time: 1000 },
      equipment: [], dialog: [], skill: structuredClone(options.neutralSkillSlots(row.id)),
      stat: options.fixtureStats.map((stat) => options.projectStats
        ? options.projectStats(row.id, structuredClone(stat)) : structuredClone(stat)),
    }));
}
